'use client';

import React, { useState, useEffect } from 'react';
import { usePOS } from '@/modules/pos/context/POSContext';
import { useRouter } from 'next/navigation';
import {
    X,
    Users,
    Move,
    SplitSquareVertical,
    Merge,
    Edit3,
    Search,
    MapPin
} from 'lucide-react';
import { mockPOSAreas } from '../mock/posData';
import { POSTable, TableStatus } from '../types/pos';

export const TablesPage: React.FC = () => {
    const { setTable, moveTable } = usePOS();
    const router = useRouter();

    const [activeArea, setActiveArea] = useState(mockPOSAreas[0]?.id);
    const [selectedTable, setSelectedTable] = useState<POSTable | null>(null);
    const [isMoveMode, setIsMoveMode] = useState(false);
    const [tableToMove, setTableToMove] = useState<POSTable | null>(null);

    // Get tables from context (local storage persistence)
    // In a real app, this would be fetched from the context state
    // For now we re-read from localStorage to ensure we have the latest updates
    const [localTables, setLocalTables] = useState<POSTable[]>([]);

    useEffect(() => {
        const fetchTables = () => {
            const savedTables = localStorage.getItem('pos_tables');
            if (savedTables) {
                setLocalTables(JSON.parse(savedTables));
            }
        };
        fetchTables();
        // Poll for changes or listen to custom event if needed
        const interval = setInterval(fetchTables, 1000);
        return () => clearInterval(interval);
    }, []);

    const filteredTables = localTables.filter(t => t.areaId === activeArea);

    const handleTableClick = (table: POSTable) => {
        if (isMoveMode && tableToMove) {
            if (table.status === 'FREE') {
                moveTable(tableToMove.id, table.id);
                setIsMoveMode(false);
                setTableToMove(null);
                setSelectedTable(null);
            }
            return;
        }

        if (table.status === 'FREE') {
            setTable(table);
            router.push('/pos/new-order');
        } else {
            setSelectedTable(table);
        }
    };

    const getStatusColor = (status: TableStatus) => {
        switch (status) {
            case 'FREE': return 'bg-brand';
            case 'OCCUPIED': return 'bg-white border-2 border-brand';
            case 'RESERVED': return 'bg-brand/20';
            default: return 'bg-brand/10';
        }
    };

    const getStatusBg = (status: TableStatus) => {
        switch (status) {
            case 'FREE': return 'bg-white border-brand text-brand hover:bg-brand/5';
            case 'OCCUPIED': return 'bg-brand border-brand text-white shadow-lg shadow-brand/20';
            default: return 'bg-white border-brand/20 text-brand/60';
        }
    };

    return (
        <div className="flex h-screen bg-white text-brand font-sans overflow-hidden">
            {/* AREA SELECTION SIDEBAR */}
            <aside className="w-64 bg-white border-r border-brand/10 flex flex-col flex-shrink-0">
                <div className="p-6 border-b border-brand/10 flex items-center justify-between">
                    <h2 className="text-xl font-black tracking-tight text-brand">Areas</h2>
                    <MapPin size={20} className="text-brand/40" />
                </div>
                <div className="flex-1 p-4 flex flex-col gap-2">
                    {mockPOSAreas.map((area) => (
                        <button
                            key={area.id}
                            onClick={() => setActiveArea(area.id)}
                            className={`px-6 py-4 rounded-2xl text-left font-bold transition-all ${activeArea === area.id
                                ? 'bg-brand text-white shadow-lg shadow-brand/20'
                                : 'text-brand/40 hover:bg-brand/5 hover:text-brand'
                                }`}
                        >
                            {area.name}
                        </button>
                    ))}
                </div>
                <div className="p-6 border-t border-brand/10 text-center">
                    <button
                        onClick={() => router.push('/pos/home')}
                        className="text-xs font-black text-brand/40 uppercase tracking-widest hover:text-brand transition-all flex items-center justify-center gap-2 mx-auto"
                    >
                        <X size={14} /> Close Table View
                    </button>
                </div>
            </aside>

            {/* TABLE GRID */}
            <main className="flex-1 flex flex-col relative min-w-0">
                <header className="h-20 bg-white border-b border-brand/10 px-8 flex items-center justify-between flex-shrink-0">
                    <div className="flex items-center gap-4">
                        <h1 className="text-2xl font-black tracking-tight text-brand">Select Table</h1>
                        <span className="px-3 py-1 bg-brand/5 rounded-lg text-xs font-black text-brand/60 uppercase tracking-widest border border-brand/10">
                            {mockPOSAreas.find(a => a.id === activeArea)?.name}
                        </span>
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="flex items-center gap-4">
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full bg-brand"></div>
                                <span className="text-[10px] font-black uppercase tracking-widest text-brand/40">Free</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-3 h-3 rounded-full border-2 border-brand"></div>
                                <span className="text-[10px] font-black uppercase tracking-widest text-brand/40">Occupied</span>
                            </div>
                        </div>
                        <div className="h-8 w-px bg-brand/10"></div>
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-brand/40" size={16} />
                            <input
                                type="text"
                                placeholder="Search table..."
                                className="bg-white border border-brand/20 rounded-xl pl-10 pr-4 py-2 text-sm focus:border-brand outline-none w-48 transition-all text-brand placeholder:text-brand/20"
                            />
                        </div>
                    </div>
                </header>

                <div className="flex-1 p-8 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6 overflow-y-auto custom-scrollbar">
                    {filteredTables.map((table) => (
                        <button
                            key={table.id}
                            onClick={() => handleTableClick(table)}
                            className={`relative h-48 rounded-[2.5rem] p-8 border-2 transition-all flex flex-col justify-between group active:scale-95 ${getStatusBg(table.status)} ${isMoveMode && table.status === 'FREE' ? 'ring-4 ring-brand/30 border-brand animate-pulse' : ''
                                }`}
                        >
                            {/* Table Seat Indicator */}
                            <div className="flex items-center justify-between">
                                <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${table.status === 'FREE' ? 'bg-brand/20 text-brand border-brand/20' : 'bg-rose-500/20 text-rose-500 border-rose-500/20'
                                    }`}>
                                    {table.status}
                                </div>
                                <div className="flex items-center gap-1.5 text-neutral-500 group-hover:text-neutral-300 transition-all font-bold">
                                    <Users size={16} />
                                    <span className="text-sm">{table.seats}</span>
                                </div>
                            </div>

                            <div className="text-left">
                                <h3 className={`text-2xl font-black tracking-tight mb-1 ${table.status === 'OCCUPIED' ? 'text-white' : 'text-neutral-300'}`}>
                                    {table.name}
                                </h3>
                                {table.orderId && (
                                    <div className="text-[10px] font-black text-rose-400 uppercase tracking-widest leading-none">
                                        {table.orderId}
                                    </div>
                                )}
                            </div>

                            {/* Status Dot */}
                            <div className={`absolute bottom-6 right-6 w-3 h-3 rounded-full ${getStatusColor(table.status)} shadow-lg shadow-black/20`}></div>
                        </button>
                    ))}
                </div>

                {/* MOVE MODE OVERLAY */}
                {isMoveMode && (
                    <div className="absolute inset-x-0 bottom-0 bg-brand p-6 flex items-center justify-between text-white animate-in slide-in-from-bottom duration-300 z-20">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center">
                                <Move size={24} />
                            </div>
                            <div>
                                <h4 className="font-black text-lg leading-none">Moving Order from {tableToMove?.name}</h4>
                                <p className="text-white/80 text-sm font-medium">Select a free target table to complete the move</p>
                            </div>
                        </div>
                        <button
                            onClick={() => { setIsMoveMode(false); setTableToMove(null); }}
                            className="px-8 py-3 bg-white text-brand rounded-xl font-black text-sm uppercase tracking-widest"
                        >
                            Cancel Move
                        </button>
                    </div>
                )}
            </main>

            {/* ORDER DETAILS PANEL (for occupied tables) */}
            {selectedTable && !isMoveMode && (
                <aside className="w-[400px] bg-white border-l border-brand/10 flex flex-col flex-shrink-0 animate-in slide-in-from-right duration-300">
                    <header className="p-8 border-b border-brand/10 flex items-center justify-between">
                        <div>
                            <div className="text-[10px] font-black text-brand/60 uppercase tracking-widest mb-1">Active Table</div>
                            <h2 className="text-2xl font-black text-brand">{selectedTable.name}</h2>
                        </div>
                        <button
                            onClick={() => setSelectedTable(null)}
                            className="w-10 h-10 bg-brand/5 rounded-full flex items-center justify-center text-brand/40 hover:text-brand transition-all"
                        >
                            <X size={20} />
                        </button>
                    </header>

                    <div className="flex-1 p-8 overflow-y-auto custom-scrollbar text-brand">
                        <div className="flex items-center justify-between mb-8">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-brand/40 uppercase tracking-widest leading-none mb-1">Order #</span>
                                <span className="text-lg font-black text-brand">{selectedTable.orderId}</span>
                            </div>
                            <div className="px-3 py-1 bg-brand/10 border border-brand/20 text-brand rounded-lg text-[10px] font-black uppercase tracking-widest">
                                PENDING
                            </div>
                        </div>

                        {/* Dummy Items */}
                        <div className="space-y-6">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 bg-brand/5 rounded-lg flex items-center justify-center text-xs font-black text-brand/60">1x</div>
                                    <div className="text-sm font-bold text-brand/80">Truffle Mushroom Pizza</div>
                                </div>
                                <span className="text-sm font-black text-brand">$24.50</span>
                            </div>
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 bg-brand/5 rounded-lg flex items-center justify-center text-xs font-black text-brand/60">2x</div>
                                    <div className="text-sm font-bold text-brand/80">Classic Margarita</div>
                                </div>
                                <span className="text-sm font-black text-brand">$32.00</span>
                            </div>
                        </div>

                        <div className="mt-12 pt-12 border-t border-brand/10">
                            <div className="flex items-center justify-between mb-4">
                                <span className="text-brand/40 font-bold">Subtotal</span>
                                <span className="text-brand/80 font-black">$56.50</span>
                            </div>
                            <div className="flex items-center justify-between mb-8 text-2xl">
                                <span className="font-black text-brand tracking-tight">Total</span>
                                <span className="font-black text-brand tracking-tight">$61.20</span>
                            </div>
                        </div>
                    </div>

                    <footer className="p-8 bg-brand/5 border-t border-brand/10 grid grid-cols-2 gap-4">
                        <button
                            disabled
                            className="flex items-center justify-center gap-2 p-4 bg-white text-brand/20 rounded-2xl text-xs font-black uppercase tracking-widest cursor-not-allowed border border-brand/10 transition-all"
                        >
                            <SplitSquareVertical size={16} /> Split
                        </button>
                        <button
                            disabled
                            className="flex items-center justify-center gap-2 p-4 bg-white text-brand/20 rounded-2xl text-xs font-black uppercase tracking-widest cursor-not-allowed border border-brand/10 transition-all"
                        >
                            <Merge size={16} /> Merge
                        </button>
                        <button
                            onClick={() => { setIsMoveMode(true); setTableToMove(selectedTable); }}
                            className="flex items-center justify-center gap-2 p-4 bg-white text-brand rounded-2xl text-xs font-black uppercase tracking-widest border-2 border-brand shadow-lg shadow-brand/10 active:scale-95 transition-all"
                        >
                            <Move size={16} /> Move Order
                        </button>
                        <button
                            onClick={() => router.push('/pos/new-order')}
                            className="flex items-center justify-center gap-2 p-4 bg-brand text-white rounded-2xl text-xs font-black uppercase tracking-widest border border-brand shadow-lg shadow-brand/20 active:scale-95 transition-all hover:bg-brand-dark"
                        >
                            <Edit3 size={16} /> Edit Order
                        </button>
                    </footer>
                </aside>
            )}
        </div>
    );
};
